entries[1247525] = { ["name"] = "Sphärenzauberei", ["text"] = "Sofort\nArkan\nSplitterschaden um 8% erhöht. 'Arkane Kugel' gewährt mit einer Chance von 100% bis zu 8-mal einen Stapel 'Arkane Harmonie'. Bei Erreichen von 20 Stapeln 'Arkane Harmonie' erhaltet Ihr 'Intuition' zu 100% Effektivität. lang um 8%.\n\nFeuer\nSplitterschaden um 8% erhöht. 'Arkane Kugel' gewährt mit einer Chance von 100% bis zu 8-mal einen Stapel 'Arkane Harmonie'. Wenn 'Kaltfront' eine 'Gefrorene Kugel' beschwört, erhöht sich Euer Zauberschaden 10 Sek. lang um 8%.\n\nFrost\nWenn 'Gefrorene Kugel' mindestens einem Gegner Schaden zufügt, gewährt sie mit einer Chance von 15% einen Stapel 'Kaltfront'. Wenn 'Kaltfront' eine 'Gefrorene Kugel' beschwört, erhöht sich Euer Zauberschaden 10 Sek. lang um 8%." }
