entries[1247901] = { ["name"] = "Stabilisierte Zeit", ["text"] = "100 Meter Reichweite\nSofort\nEternus beschwört einen manifestierte Zeitweg, der ' Zeit destabilisieren ' wirkt und allen Spielercharakteren 30 Arkanschaden zufügt.\n\nBeim Tod teilt sich der manifestierte Zeitweg in 3 kleinere manifestierte Zeitwege auf und gewährt Spielercharakteren ' Stabilisierte Zeit ', wodurch Tempo, kritische Trefferchance, Vielseitigkeit und Meisterschaft 30 Sek. lang erhöht werden." }
