entries[1248123] = { ["name"] = "Zerfasern", ["text"] = "Sofort\nEternus beschwört alternative böse Gruppenmitglieder. Eternus beschwört böse Zeitlinienversionen von Spielercharakteren, die versuchen, Essenz zu stehlen. Wenn sie ihr Ziel erreichen, wirken sie ' Gestohlene Essenz ' und verringern 30 Sek. lang maximale Gesundheit, verursachten Schaden und hervorgerufene Heilung um 6 %.\n\nDie instabilen Kopien ' Zerfasern ' ständig, wodurch sie alle 1 Sek. Arkanschaden in Höhe von 5% ihrer maximalen Gesundheit erleiden.\n\nBei ihrem Tod wirken sie stattdessen ' Verschmolzene Essenz ' und erhöhen maximale Gesundheit, verursachten Schaden und hervorgerufene Heilung ihres Ziels 20 Sek. lang um 30%." }
entries[1248128] = { ["name"] = "Galaktisches Schmettern", ["text"] = "Unbegrenzte Reichweite\nSofort\nNeben Salhadaar selbst erscheinen Abbilder von ihm, die ihre Ziele mit galaktischer Kraft zerschmettern, alle Spielercharaktere mit ' Zwielichtnarbe ' belegen und ihnen 12142510 kosmischen Schaden zufügen. Spielercharaktere, die weiter von den einzelnen Zielen entfernt sind, erleiden weniger Schaden.\n\nSalhadaars Primärziel ist ' Sternenzerschmettert '. An jedem Einschlagsort entsteht ' Dunkler Stern '." }
