entries[1248133] = { ["name"] = "Leerenriss", ["text"] = "Unbegrenzte Reichweite\nWirken in 3 sek.\nDie unaufhaltsame Monstrosität entfesselt eine Welle nekrotischer Energie in Richtung eines zufälligen Spielercharakters, die allen getroffenen Spielercharakteren 75 Schattenschaden zufügt." }
entries[1248134] = { ["name"] = "Dunkler Stern", ["text"] = "Unbegrenzte Reichweite\nSofort\nEin Stern materialisiert sich aus dem Wirbelnden Nether und zieht Spielercharaktere 5 Sek. lang in sein Zentrum.\n\nWährend des Entstehungsprozesses werden Spielercharaktere innerhalb von ' Dunkler Stern ' ' Atomisiert ', während ' Zwielichtstacheln ' nach außen ausstrahlt. Fügt allen Spielercharakteren alle 1 Sek. 56215 kosmischen Schaden zu." }
