entries[1249462] = { ["name"] = "Abmachung: Kartell Zo", ["text"] = "Sofort\nTrefft eine Abmachung mit dem Kartell Zo und erlangt das Recht, Euch für eine Woche als eines ihrer Mitglieder zu bezeichnen.\n\nKriegsmeutenvertrag\nIhr könnt nur mit einem Kartell pro Woche einen Handel eingehen. Dieser Effekt gilt für Eure gesamte Kriegsmeute." }
entries[1249463] = { ["name"] = "Abmachung: Kartell Zo", ["text"] = "Wirken in 3.5 sek.\nReagenzien:\nFrisches Pergament , Manageschmiedetes Instrument , Sonnige Tinte (25)\nVandalen der Manaschmiede\nRuhmstufe:\n8\nOrt:\nSchattenpunkt\n\nAbmachung: Kartell Zo\nBenutzen: Trefft eine Abmachung mit dem Kartell Zo und erlangt das Recht, Euch für eine Woche als eines ihrer Mitglieder zu bezeichnen.\n\nKriegsmeutenvertrag\nIhr könnt nur mit einem Kartell pro Woche einen Handel eingehen. Dieser Effekt gilt für Eure gesamte Kriegsmeute.\n70\n\"Ein von Schreibern aufgesetzter kurzfristiger \"Vertrag\", der die Loyalität einer Kriegsmeute zu einem Mittlerkartell bekundet.\"" }
entries[1249464] = { ["name"] = "Gabe von Elune", ["text"] = "Sofort\nTierherrschaft, Überleben\nErhöht den Schaden von 'Lauffeuerbombe' um 10%. Wenn 'Lunarsturm' abklingt, erhaltet Ihr eine 'Gabe von Elune', wodurch Ihr mit 'Lauffeuerbombe'[Quellwert] 2-mal um 150 erhöhten anfänglichen Schaden als Arkanschaden verursacht.\n\nTreffsicherheit\nErhöht den Schaden von 'Schnellfeuer' um 25%. Wenn 'Lunarsturm' abklingt, erhaltet Ihr eine 'Gabe von Elune', wodurch Ihr mit 'Gezielter Schuss'[Quellwert] 2-mal um 10 erhöhten Schaden als Arkanschaden verursacht.", ["unresolvedValues"] = true }
entries[1249465] = { ["name"] = "Abmachung: Kartell Ba", ["text"] = "Sofort\nTrefft eine Abmachung mit dem Kartell Ba und erlangt das Recht, Euch für eine Woche als eines ihrer Mitglieder zu bezeichnen.\n\nKriegsmeutenvertrag\nIhr könnt nur mit einem Kartell pro Woche einen Handel eingehen. Dieser Effekt gilt für Eure gesamte Kriegsmeute." }
entries[1249466] = { ["name"] = "Abmachung: Kartell Ba", ["text"] = "Wirken in 3.5 sek.\nReagenzien:\nFrisches Pergament , Manageschmiedetes Instrument , Sonnige Tinte (25)\nVandalen der Manaschmiede\nRuhmstufe:\n8\nOrt:\nSchattenpunkt\n\nAbmachung: Kartell Ba\nBenutzen: Trefft eine Abmachung mit dem Kartell Ba und erlangt das Recht, Euch für eine Woche als eines ihrer Mitglieder zu bezeichnen.\n\nKriegsmeutenvertrag\nIhr könnt nur mit einem Kartell pro Woche einen Handel eingehen. Dieser Effekt gilt für Eure gesamte Kriegsmeute.\n70\n\"Ein von Schreibern aufgesetzter kurzfristiger \"Vertrag\", der die Loyalität einer Kriegsmeute zu einem Mittlerkartell bekundet.\"" }
