entries[1249468] = { ["name"] = "Abmachung: Kartell Om", ["text"] = "Wirken in 3.5 sek.\nReagenzien:\nFrisches Pergament , Manageschmiedetes Instrument , Sonnige Tinte (25)\nVandalen der Manaschmiede\nRuhmstufe:\n8\nOrt:\nSchattenpunkt\n\nAbmachung: Kartell Om\nBenutzen: Trefft eine Abmachung mit dem Kartell Om und erlangt das Recht, Euch für eine Woche als eines ihrer Mitglieder zu bezeichnen.\n\nKriegsmeutenvertrag\nIhr könnt nur mit einem Kartell pro Woche einen Handel eingehen. Dieser Effekt gilt für Eure gesamte Kriegsmeute.\n70\n\"Ein von Schreibern aufgesetzter kurzfristiger \"Vertrag\", der die Loyalität einer Kriegsmeute zu einem Mittlerkartell bekundet.\"" }
