entries[1250285] = { ["name"] = "Haigeprüftes Spitzenhorn", ["text"] = "Wirken in 1.5 sek.\nBeschwört dieses Reittier oder gibt es wieder frei.\n\"Spitzenhörner werden oft von den Pflanzen angezogen, die im Meer wachsen. Manche von ihnen haben sich dort gegen die gefährlichsten Bestien durchgesetzt, was sie zu wahren Kalu'ak macht.\"\nHandelsposten" }
entries[1250287] = { ["name"] = "Schollenschreiterspitzenhorn", ["text"] = "Wirken in 1.5 sek.\nBeschwört dieses Reittier oder gibt es wieder frei.\n\"Diese seltenen, im Azurblauen Gebirge einheimischen Kreaturen werden von den Tuskarr in der Region als gesegnet angesehen.\"\nHandelsposten" }
entries[1250288] = { ["name"] = "Felsschreiterspitzenhorn", ["text"] = "Wirken in 1.5 sek.\nBeschwört dieses Reittier oder gibt es wieder frei.\n\"Die Tuskarr verirren sich nur selten auf den Hochberg, aber die Spitzenhörner kommen oft hinunter an die Küste, um im Küstengewässer nach seltenen Delikatessen zu suchen.\"\nHandelsposten" }
entries[1250314] = { ["name"] = "Phantomblüte", ["text"] = "5 Meter Reichweite\nWirken in 2.5 sek.\nPhantomblüten sind Energieüberreste einheimischer Flora von K'aresh und lassen sich nicht in Algarirezepturen einbinden.\n\nIhr könnt Phantomblüten stattdessen auf dem Ressourcenmarkt gegen Algarimaterialien eintauschen. Die Preise ändern sich täglich, und mit etwas Geduld könnt Ihr die besten Angebote erzielen!" }
entries[1250317] = { ["name"] = "Üppige Phantomblüte", ["text"] = "5 Meter Reichweite\nWirken in 2.5 sek.\nPhantomblüten sind Energieüberreste einheimischer Flora von K'aresh und lassen sich nicht in Algarirezepturen einbinden.\n\nIhr könnt Phantomblüten stattdessen auf dem Ressourcenmarkt gegen Algarimaterialien eintauschen. Die Preise ändern sich täglich, und mit etwas Geduld könnt Ihr die besten Angebote erzielen!\n\nEinige der entdeckten Exemplare der Phantomblüte waren deutlich größer als erwartet. Einst eine der wenigen Pflanzen, die in den gnadenlosen Ödlanden der Wüsten von K'aresh überlebten, war sie in den üppigen, ungezähmten Wäldern für ihre größeren Ausprägungen bekannt." }
