entries[1250915] = { ["name"] = "Zeitverzerrte Wyrmzunge", ["text"] = "Sofort\nIn eine Wyrmzunge zeitverschoben, von den meisten Gegnern ignoriert.\nBewegungsgeschwindigkeit um 60% erhöht.\n\nKann Bronzepartikel auf Argus sehen: Sammeln von Bronzepartikeln erhöht Eure Bewegungsgeschwindigkeit und Bronzeerträge. Stapelbar, bis der Effekt endet.\n\nKampf hebt diesen Effekt auf." }
