entries[1251255] = { ["name"] = "Baumspitzenhochbergadler", ["text"] = "Wirken in 1.5 sek.\nBeschwört dieses Reittier oder gibt es wieder frei.\n\"Der majestätische Adler ist ein Symbol für den Stolz der Hochbergstämme. Die Fähigkeit dieser gewaltigen Tiere, Tauren auf ihrem Rücken zu tragen, zeugt von der schieren Größe und Stärke der Kreaturen des Hochbergs.\"\nWeltereignis:\nWoW Remix: Legion" }
entries[1251257] = { ["name"] = "Leyfrostmanasäbler", ["text"] = "Wirken in 1.5 sek.\nBeschwört dieses Reittier oder gibt es wieder frei." }
entries[1251259] = { ["name"] = "Schlüsselsteinaffix hinzufügen: Tyrannisch verstärkt", ["text"] = "Sofort\nFügt einem mythischen Schlüsselstein das Affix Tyrannisch verstärkt hinzu." }
entries[1251264] = { ["name"] = "Nachtbrunnenmanasäbler", ["text"] = "Wirken in 1.5 sek.\nBeschwört dieses Reittier oder gibt es wieder frei." }
entries[1251265] = { ["name"] = "Arkbeerenmanasäbler", ["text"] = "Wirken in 1.5 sek.\nBeschwört dieses Reittier oder gibt es wieder frei.\n\"Ihr Name rührt von ihrer optischen Ähnlichkeit mit den leuchtenden Beeren her, aus denen Arkwein hergestellt wird. Diese stolzen Katzen haben einen scharfen Sinn für die Leylinien, auf denen sie wandeln.\"\nWeltereignis:\nWoW Remix: Legion" }
entries[1251266] = { ["name"] = "Traumblitz", ["text"] = "30 Meter Reichweite\nWirken in 2 sek. 3 sek. Abklingzeit\nSchleudert Erde nach einem Gegner und verursacht 150 körperlichen Schaden." }
entries[1251279] = { ["name"] = "Teufelsvernarbter Manarochen", ["text"] = "Wirken in 1.5 sek.\nBeschwört einen teufelsvernarbten Manarochen oder gibt ihn wieder frei. Dieses Reittier passt sich Eurer Reitfertigkeit und Eurem Aufenthaltsort an.\n\"Die ledrige Haut dieses Manarochens trägt die Narben der Teufelsverderbnis und ist Zeugnis des harten Überlebenskampfes auf Argus. Er neigt noch mehr als üblich zu Aggressionsausbrüchen.\"\nWeltereignis:\nWoW Remix: Legion" }
entries[1251281] = { ["name"] = "Blutreißermanarochen", ["text"] = "Wirken in 1.5 sek.\nBeschwört einen Blutreißermanarochen oder gibt ihn wieder frei. Dieses Reittier passt sich Eurer Reitfertigkeit und Eurem Aufenthaltsort an.\n\"Die Zerschmetterung von Argus machte diese Art von Manarochen blutrünstig. Nun ernähren sie sich vom verderbten Blut aller Kreaturen, die sie zwischen ihre zahlreichen Zähne bekommen können.\"\nWeltereignis:\nWoW Remix: Legion" }
entries[1251283] = { ["name"] = "Albinomanarochen", ["text"] = "Wirken in 1.5 sek.\nBeschwört einen Albinomanarochen oder gibt ihn wieder frei. Dieses Reittier passt sich Eurer Reitfertigkeit und Eurem Aufenthaltsort an.\n\"Die Zerschmetterung von Argus ließ die Manarochen mutieren, um sich ihrer neuen Umgebung anzupassen. Manche von ihnen gaben die Pigmentierung ihrer Haut auf, um im Gegenzug ihre Sinne zu schärfen.\"\nWeltereignis:\nWoW Remix: Legion" }
entries[1251284] = { ["name"] = "Leuchtender Manarochen", ["text"] = "Wirken in 1.5 sek.\nBeschwört einen leuchtenden Manarochen oder gibt ihn wieder frei. Dieses Reittier passt sich Eurer Reitfertigkeit und Eurem Aufenthaltsort an.\n\"Manarochen können ein helles Leuchten ausstrahlen, um Beute anzulocken.\"\nWeltereignis:\nWoW Remix: Legion" }
entries[1251292] = { ["name"] = "Platzieren" }
entries[1251295] = { ["name"] = "Zwielichtrenner", ["text"] = "Wirken in 1.5 sek.\nBeschwört dieses Reittier oder gibt es wieder frei.\n\"Um Fressfeinden zu entgehen, dämpft dieser Renner das Leuchten seines Horns, wenn er sich versteckt. Provoziert man ihn, stößt er hingegen blendende Lichtblitze aus.\"\nWeltereignis:\nWoW Remix: Legion" }
entries[1251297] = { ["name"] = "Goldener Sonnenrenner", ["text"] = "Wirken in 1.5 sek.\nBeschwört dieses Reittier oder gibt es wieder frei.\n\"Dieser Freigeist liebt lange Spaziergänge am Strand und tollt gerne auf bunten Blumenwiesen herum.\"\nWeltereignis:\nWoW Remix: Legion" }
entries[1251298] = { ["name"] = "Türkisrenner", ["text"] = "Wirken in 1.5 sek.\nBeschwört dieses Reittier oder gibt es wieder frei.\n\"Benannt nach seinen einzigartig gefärbten Augen, die einem direkt in die Seele zu starren scheinen, zeigt der Türkisrenner mehr Intelligenz als seine Traumläufer-Artgenossen und ist bekannt dafür, den Charakter einer Person hervorragend einschätzen zu können.\"\nWeltereignis:\nWoW Remix: Legion" }
entries[1251300] = { ["name"] = "Düsternisalptraum", ["text"] = "Wirken in 1.5 sek.\nBeschwört dieses Reittier oder gibt es wieder frei.\n\"Diese Kreatur wurde vom Smaragdgrünen Alptraum berührt. Wenn sie einem im Traum erscheint, gilt das als Zeichen des Unglücks, und wer sie im wachen Zustand zu Gesicht bekommt, dem droht eine Katastrophe.\"\nWeltereignis:\nWoW Remix: Legion" }
entries[1251305] = { ["name"] = "Knochenross des Triumphs", ["text"] = "Wirken in 1.5 sek.\nBeschwört dieses Reittier oder gibt es wieder frei.\n\"Ein gutes Schlachtross ist treu bis auf die Knochen. Dieses Pferd hat seine sterbliche Hülle abgelegt und ist ein Vorbote heldenhafter Siege.\"\nWeltereignis:\nWoW Remix: Legion" }
entries[1251307] = { ["name"] = "Knochenross des Blutvergießens", ["text"] = "Wirken in 1.5 sek.\nBeschwört dieses Reittier oder gibt es wieder frei.\n\"Ein gutes Schlachtross ist treu bis auf die Knochen. Dieses Pferd hat seine sterbliche Hülle abgelegt und ist ein Vorbote des ewigen Kampfes.\"\nWeltereignis:\nWoW Remix: Legion" }
entries[1251309] = { ["name"] = "Knochenross der Seuche", ["text"] = "Wirken in 1.5 sek.\nBeschwört dieses Reittier oder gibt es wieder frei.\n\"Ein gutes Schlachtross ist treu bis auf die Knochen. Dieses Pferd hat seine sterbliche Hülle abgelegt und ist ein Vorbote von Krankheit und Leid.\"\nWeltereignis:\nWoW Remix: Legion" }
entries[1251311] = { ["name"] = "Knochenross des Vergessens", ["text"] = "Wirken in 1.5 sek.\nBeschwört dieses Reittier oder gibt es wieder frei.\n\"Ein gutes Schlachtross ist treu bis auf die Knochen. Dieses Pferd hat seine sterbliche Hülle abgelegt und ist ein Vorbote von Mangel und Tod.\"\nWeltereignis:\nWoW Remix: Legion" }
