entries[1251396] = { ["name"] = "Langhörniger Zobeltalbuk", ["text"] = "Wirken in 1.5 sek.\nBeschwört dieses Reittier oder gibt es wieder frei.\n\"Die Talbuks von Argus haben langes, grobes Fell in leuchtenden Farben, die die vielen Schattierungen ihres zerbrochenen Planeten widerspiegeln.\"\nWeltereignis:\nWoW Remix: Legion" }
entries[1251397] = { ["name"] = "Granatfarbener Ruinprescher", ["text"] = "Wirken in 1.5 sek.\nBeschwört dieses Reittier oder gibt es wieder frei.\n\"Mit ihrer widerstandsfähigen Panzerung tragen die Ruinprescher von Argus ihre Reiter furchtlos über das zerklüftete Ödland des Planeten und darüber hinaus.\"\nWeltereignis:\nWoW Remix: Legion" }
entries[1251398] = { ["name"] = "Langhörniger Karghuftalbuk", ["text"] = "Wirken in 1.5 sek.\nBeschwört dieses Reittier oder gibt es wieder frei.\n\"Dieser teufelsdurchdrungene Talbuk trägt Narben von Jahrzehnten des Kampfes und ist damit das perfekte Reittier für unerschrockene Abenteurer.\"\nWeltereignis:\nWoW Remix: Legion" }
entries[1251399] = { ["name"] = "Langhörniger Argustalbuk", ["text"] = "Wirken in 1.5 sek.\nBeschwört dieses Reittier oder gibt es wieder frei.\n\"Nur eine kleine Zahl von Talbuks hat es geschafft, von der Ausbeutung ihrer Heimatwelt durch die Legion unberührt zu bleiben. Diese Unbeugsamkeit macht sie zu wahrlich noblen Reittieren.\"\nWeltereignis:\nWoW Remix: Legion" }
entries[1251400] = { ["name"] = "Langhörniger Berylltalbuk", ["text"] = "Wirken in 1.5 sek.\nBeschwört dieses Reittier oder gibt es wieder frei.\n\"Dieser wilde Talbuk ist in den Ruinen von Argus heimisch und hat Jahrzehnte des Konflikts überlebt.\"\nWeltereignis:\nWoW Remix: Legion" }
