entries[1251545] = { ["name"] = "Astrales Schröpfen", ["text"] = "Sofort\nCa. 2 Procs pro Minute\nEure schädlichen Zauber und Fähigkeiten haben eine Chance, latente Energien aus Eurer Umgebung zu fokussieren, um Arkanschaden zu verursachen, der zwischen Eurem Ziel und Gegnern in der Nähe aufgeteilt wird. Gegner mit weniger als 35% Gesundheit erleiden 20% zusätzlichen Schaden.\n(100ms Abklingzeit)" }
entries[1251549] = { ["name"] = "Astrale Rekonstitution", ["text"] = "Sofort\nCa. 2 Procs pro Minute\nEure hilfreichen Zauber und Fähigkeiten haben eine Chance, schlummernde Energien zu sammeln, um einen Verbündeten zu heilen. Überschüssige Heilung aus diesem Effekt gewährt einen Absorptionsschild.\n(100ms Abklingzeit)" }
entries[1251551] = { ["name"] = "Portal nach Tazavesh" }
entries[1251553] = { ["name"] = "Astraler Schutz", ["text"] = "Sofort\nCa. 2 Procs pro Minute\nEure Zauber und Fähigkeiten haben eine hohe Chance, die Euch umgebende Energie zu verschmelzen, um Euch einen Schild zu gewähren, der den erlittenen Schaden von 20% bis zu einem Höchstwert verringert.\n\nWenn Eure Gesundheit unter 40% sinkt, erhaltet Ihr diesen Effekt mit einer Effektivität von 500%. Dieser Effekt kann nur einmal alle 6 Min. auftreten.\n(100ms Abklingzeit)" }
entries[1251565] = { ["name"] = "Portal nach Revendreth" }
