entries[1252096] = { ["name"] = "Schwerer Donner", ["text"] = "Sofort\nEuer 'Ionisierender Schlag' verursacht 100% mehr Schaden. Zusätzlich erhaltet Ihr beim Auslösen von 'Ionisierender Schlag' eine Ladung von 'Donnerexplosion‘, und Eure nächste 'Donnerexplosion' verursacht 100% mehr Schaden." }
