entries[1252185] = { ["name"] = "Infusionspylonen", ["text"] = "50 Meter Reichweite\nSofort\nDie Arkanpylonen der Kammer pumpen mittels Arkanstrahlen Energie in Loom'ithar und lösen bei Kontakt ' Überschüssige Nova ' aus.\n\nSpielercharaktere innerhalb des Strahls versperren ihm den Weg, erleiden 606071 Arkanschaden und erhalten alle 1 Sek. einen Stapel ' Hyperinfusion '. Dieser Effekt ist stapelbar." }
entries[1252190] = { ["name"] = "Flug der Val'kyr", ["text"] = "Eure Fähigkeit ' Richturteil des Verteidigers ' segnet bis zu 5 Verbündete in der Nähe, wodurch sie 12 Sek. lang von Val'kyr beschützt werden.\n\nDie Val'kyr fangen tödliche Angriffe ab und heilen das Ziel stattdessen vollständig. Dieser Effekt kann nur einmal alle 8 Min. auf demselben Ziel ausgelöst werden." }
entries[1252191] = { ["name"] = "Flug der Val'kyr" }
entries[1252192] = { ["name"] = "Flug der Val'kyr", ["text"] = "100 Meter Reichweite\nSofort\nEure Fähigkeit ' Richturteil des Verteidigers ' segnet bis zu 5 Verbündete in der Nähe, wodurch sie 12 Sek. lang von Val'kyr beschützt werden.\n\nDie Val'kyr fangen tödliche Angriffe ab und heilen das Ziel stattdessen vollständig. Dieser Effekt kann nur einmal alle 8 Min. auf demselben Ziel ausgelöst werden." }
entries[1252193] = { ["name"] = "Auserwählter Odyns", ["text"] = "Unbegrenzte Reichweite\nSofort\nEure Fähigkeit ' Richturteil des Verteidigers ' segnet bis zu 5 Verbündete in der Nähe, wodurch sie 12 Sek. lang von Val'kyr beschützt werden.\n\nDie Val'kyr fangen tödliche Angriffe ab und heilen das Ziel stattdessen vollständig. Dieser Effekt kann nur einmal alle 8 Min. auf demselben Ziel ausgelöst werden." }
entries[1252196] = { ["name"] = "Gabe erbitten", ["text"] = "Sofort\nIhr habt Eure Gabe an den zeitverzerrten Obelisken nicht abgeschlossen. Wiederherstellungseffekte durch zeitverzerrte Obelisken sind deutlich reduziert." }
entries[1252198] = { ["name"] = "Himmlische Befehle", ["text"] = "Nach dem Wirken von ' Richturteil des Verteidigers ' wird die Fähigkeit zu ' Ins Getümmel '.\n\nIns Getümmel\nStürmt voller Tatkraft vorwärts, streckt alle Gegner auf Eurem Weg nieder und fügt ihnen [(168% Angriffs-/Zaubermacht)] Heiligschaden zu.\n\nWird nach dem Wirken zu ' Lichtgebundene Passage '.\n\nLichtgebundene Passage\nDas Betreten einer Säule heiligen Lichts fügt Gegnern innerhalb von 6 Metern bis zu [(168% Angriffs-/Zaubermacht)] Heiligschaden zu und heilt Verbündete in diesem Bereich um [(168% Angriffs-/Zaubermacht)] Gesundheit. Ihr werdet dabei 20 Meter zurückteleportiert, oder bis Ihr auf ein Objekt trefft.\n\nWährend ' Lichtgeschmiedet ' erhaltet Ihr außerdem ' Echo des Lichts '.\n\nEcho des Lichts\nIhr strahlt heiliges Licht aus, das sich alle 3 Sek. zu Partikeln verbindet. Der Kontakt mit einem Partikel fügt Gegnern in der Nähe [(168% Angriffs-/Zaubermacht)] Heiligschaden zu oder stellt bei Verbündeten innerhalb von 60 Metern [(168% Angriffs-/Zaubermacht)] Gesundheit wieder her." }
